def maximum_segments(n, a, b, c):
    if b <= c:
        max_segments = a * n // (a + b)
    else:
        max_segments = a * n // (a + c)
    if a < b < c:
        max_segments += (a * b + a * c) - (max_segments * (a + b + c))
    return max_segments
