def dealnnoy_num(n, k):
    # Initialize the first k values of the Delannoy numbers
    delnnoys = [0] * (k + 1)
    delnnoys[0] = 1 if k == 0 else 0
    if k >= 1:
        delnnoys[1] = 1

    # Calculate the Delannoy numbers up to n
    for i in range(2, n + 1):
        for j in range(1, k + 1):
            delnnoys[j] += delnnoys[j-1] + delnnoys[j]

    return delnnoys[k]
```

