def find_Min_Swaps(A, n):
    min_swaps = 0
    def swap(a, b, l):
        a[b], a[l] = a[l], a[b]

    def sort(arr, l, r):
        if l >= r:
            return 0

        mid = l + (r - l) // 2
        left_swaps = sort(arr, l, mid)
        right_swaps = sort(arr, mid + 1, r)

        i = mid + 1
        count = 0
        for j in range(l, mid + 1):
            while i <= r and arr[j] > arr[i]:
                i += 1
                count += 1
            swap(arr, j, i)

        min_swaps += left_swaps + right_swaps + count
        return min_swaps

    return sort(A, 0, n - 1)
