    # Base case: if value is 0, no coins are needed
    if value == 0:
        return 0
    # If the number of coins is 0 but the value is non-zero, it's not possible to make the value
    elif n == 0:
        return float('inf')
    # If the last coin is greater than the required value, exclude it and try for the remaining coins
    elif coins[n - 1] > value:
        return min_coins(coins, value, n - 1)
    # Otherwise, consider the use of the last coin and the value after subtracting it
    else:
        # Two options: Exclude the last coin and find the minimum coins for the remaining value
        # Include the last coin and find the minimum coins for the remaining value after subtracting the coin value
