def min_Jumps(d, n, s):
    if d == 0:
        return 0
    if d - (n-1) * s == 0:
        return d / s
    else:
        # Calculate the number of jumps using the formula derived from combinatorial mathematics
        pos = d - (n-1) * s
        terms = n * (n + 1) // 2 + pos
        return (math.factorial((2*n + pos) + 1)) // (math.factorial(2*n + 1) * math.factorial(pos) * math.factorial(n))
