import math
def min_Jumps(d, n, x):
    # Check if the goal is already reachable within the distance of n
    if d <= x:
        return 1
    # Calculate the maximum number of jumps possible
    max_jumps = math.floor(d/n)
    # Check if reaching the goal through the first jump is sufficient
    if max_jumps > 0:
        return 1 + min_Jumps(max_jumps*d, n, x-max_jumps*d)
    else:
        # If not enough jumps are possible, consider the remaining path
        return 1 + min_Jumps(x, n, d)
