def set_Right_most_Unset_Bit(num):
    if num == 0:  # If the number is 0, set all bits
        return intbitset("111...1", len(bin(num)))

    # Count the number of set bits from the right
    num_set_bits = 0
    while num:
        num_set_bits += num & 1
        num >>= 1

    # If all bits are already set, return the number
    if num_set_bits == len(bin(num)):
        return num | 1 << (len(bin(num)) - 1)

    # Set the right most unset bit
    result = num | 1 << (len(bin(num)) - 1 - num_set_bits)
    return result
