def dp(str1, str2, m, n):
    # Creating a dp array to store the lengths of the longest common subsequences
    dp = [[0] * (n + 1)] * (m + 1)

    # Filling the dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                # If characters match, current length is 1 plus length of the previous sequences
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                # If characters do not match, current length is the maximum of the lengths of the subsequences excluding the current characters
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the shortest supersequence is the sum of m and n minus the length of the longest common subsequence
    return m + n - dp[m][n]
