def product_Equal(n):
    # Since the product of digits at even and odd places will be the same
    # if the number is symmetric with respect to its center digit
    # (i.e., if the number's first and last digits, second and penultimate digits, etc. are equal)
    if str(n)[:int(len(str(n))/2]) == str(n)[int(len(str(n))/2+1:]:
        # Calculate product of digits in even and odd positions
        product_even = 1
        product_odd = 1
        for i in range(len(str(n))):
            if i % 2 == 0:
                product_even *= int(str(n)[i])
            else:
                product_odd *= int(str(n)[i])
        # Return True if products are equal, False otherwise
        return product_even == product_odd
    else:
        return False
