def maxAverageOfPath(matrix, n):
    def calculate_average(matrix, path):
        return sum(matrix[i][j] for i, j in path) / len(path)

    def dfs(matrix, current_path, current_sum, max_sum):
        if not matrix or not current_path or len(current_path) >= n:
            return max(current_sum, max_sum)

        max_sum = dfs(matrix, current_path + [(current_path[-1][0] + 1, current_path[-1][1])], current_sum + matrix[current_path[-1][0]][current_path[-1][1]], max_sum)
        max_sum = dfs(matrix, current_path + [(current_path[-1][0] - 1, current_path[-1][1])], current_sum + matrix[current_path[-1][0]][current_path[-1][1]], max_sum)
        max_sum = dfs(matrix, current_path + [(current_path[-1][0], current_path[-1][1] + 1)], current_sum + matrix[current_path[-1][0]][current_path[-1][1]], max_sum)
        max_sum = dfs(matrix, current_path + [(current_path[-1][0], current_path[-1][1] - 1)], current_sum + matrix[current_path[-1][0]][current_path[-1][1]], max_sum)

        return max_sum

    max_sum = -float('inf')
    for i in range(n):
        for j in range(n):
            max_sum = max(max_sum, dfs(matrix, [(i, j)], matrix[i][j], max_sum))

    return max_sum
