from collections import Counter

def count_element_freq(mixed_tuple):
    # Initialize an empty dictionary
    freq_dict = {}
    # Iterate through the mixed tuple
    for item in mixed_tuple:
        # If the item is a tuple, recursively count the elements in it
        if isinstance(item, tuple):
            freq_dict.update(count_element_freq(item))
        else:
            # Count the element and store it in the dictionary
            freq_dict[item] = freq_dict.get(item, 0) + 1
    # Return the frequency dictionary
    return Counter(freq_dict)
