    for i in range(n - 2):

        # Avoid duplicate triplets
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        l, r = i + 1, n - 1
        while l < r:

            # Check if the sum of current triplet is equal to the target_sum
            total_sum = nums[i] + nums[l] + nums[r]

            if total_sum == target_sum:
                return (nums[i], nums[l], nums[r])
