def maximum_segments(n, a, b, c):
    max_segments = 0
    # Find all possible combinations using iterations
    for i in range(n//a + 1):
        for j in range(n//(b+a) + 1):
            k = (n%(b+a)) // c
            max_segments = max(max_segments, i + j + k)
            if (n%(b+a)) % c != 0:
                k += 1
                max_segments = max(max_segments, i + j + k)
            else:
                k = (n%(b+a)) // c
                max_segments = max(max_segments, i + j + k - 1)
    return max_segments
