def find_kth(arr1, arr2, k1, k2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0
    # Loop until k is not zero
    while k:
        # If the current element in array1 is smaller, move pointer i forward
        if i < len(arr1) and k1 < len(arr1):
            if j < len(arr2) and k2 < len(arr2):
                if arr1[i] <= arr2[j]:
                    i += 1
                else:
                    j += 1
            else:
                i += 1
        # If k1 is exhausted, move pointer j forward
        elif k1 == len(arr1) and j < len(arr2):
            j += 1
        # If k2 is exhausted, move pointer i forward
        elif j == len(arr2) and k1 < len(arr1):
            i += 1
        # If both arrays have been exhausted, return the (k-1)th element
        else:
            return (arr1[i-1] if i-1 >= 0 else float("-inf")) if i > 0 else max(arr2)
        # Decrement k for the next iteration
        k -= 1

