    i, j, c = 0, 0, 0
    while i < a_len and j < b_len and c <= k - 1:
        if A[i] < B[j]:
            if c == k - 1:
                return A[i]
            i += 1
            c += 1
        else:
            if c == k - 1:
                return B[j]
            j += 1
            c += 1
    while i < a_len and c <= k - 1:
