def find_kth(arr1, arr2, k1, k2, kth_element):
    # Check if the k1 or k2 are out of bounds
    if k1 > len(arr1) or k2 > len(arr2):
        return "Error: One of the input lists is too small."

    # Calculate the positions from where elements from both arrays need to be considered
    pos1 = k1 - 1 if k1 > 0 else 0
    pos2 = k2 - 1 if k2 > 0 else 0

    while pos1 < len(arr1) and pos2 < len(arr2):
        if arr1[pos1] < arr2[pos2]:
            if kth_element <= 1:
                kth_element = arr1[pos1]
                return kth_element  # Last element found
            kth_element -= 1
            pos1 += 1
        else:
            if kth_element <= 1:
                kth_element = arr2[pos2]
                return kth_element  # Last element found
            kth_element -= 1
            pos2 += 1

    # If one array is exhausted, return the remaining element from the other
    if pos1 == len(arr1):
        return arr2[pos2 + kth_element - 1]
    else:
        return arr1[pos1 + kth_element - 1]

