                if s1[j] != s2[j]:
                    mismatch_count -= 1
                    if s1[j] == '1':
                        one_count += 1
                    else:
                        zero_count += 1
                    if mismatch_count == 0:
                        break

            # Calculate the number of swaps needed
            if zero_count + one_count == 0:
                return 1  # The rest of the string is the same as the target string
            else:
                swaps_needed = zero_count + one_count - 1
                swap_count += swaps_needed

