def get_median(nums1, nums2, n):
    left = 0
    right = n - 1
    total_numbers = n
    while left <= right:
        mid1 = left + (right - left) // 2
        mid2 = total_numbers - mid1 - 1
        left_element = None
        right_element = None

        if mid1 < n:
            left_element = nums1[mid1]
        if mid2 < n:
            right_element = nums2[mid2]

        if left_element == None:
            left_element = float('-inf')
        if right_element == None:
            right_element = float('inf')

        if left_element <= right_element:
            if mid1 < n:
                right = mid1 - 1
            else:
                return (left_element + right_element) / 2
        else:
            if mid2 < n:
                left = mid1 + 1
            else:
                return (left_element + right_element) / 2
