def min_Jumps(x,m,n):
    # Dictionary to store calculated results
    dp = {}  
    def find_pseudo(x,m,n, dp):
        # Base case: if point is reached at origin, return 0 jumps
        if x == 0:
            return 0
        # If the result for this point is already calculated, return it
        if x in dp:
            return dp[x]
        # If point goes outside dungeon, return infinite jumps
        if x > m:
            dp[x] = float('inf')
            return float('inf')
        min_possible_jumps = float('inf')  # Initialize minimum jumps to infinite

        # Iterate over possible jumps from current point
        for i in range(1, min(m, x + n)):
            # Calculate jumps required from previous point
            jumps_from_previous_point = find_pseudo(x - i, m, n, dp)
            # Update minimum possible jumps if a shorter path is found
            min_possible_jumps = min(min_possible_jumps, jumps_from_previous_point + 1)

        # Store the result in the dictionary
        dp[x] = min_possible_jumps
        return dp[x]

    # Calculate the minimum jumps required from given point to the origin
    return find_pseudo(x, m, n, dp)
```

