def sum_of_odd_Factors(num):
    sum_odd_factors = 1  # Initial sum of the number itself
    # Loop through possible divisors
    for i in range(1, int(sqrt(num)) + 1):
        if num % i == 0:
            # If the divisor is odd, add it to the sum
            if i % 2 != 0:
                sum_odd_factors += i
            # If the divisor is different from the perfect square, add the complementary divisor
            if i != num // i and (num // i % 2 != 0):
                sum_odd_factors += num // i
    return sum_odd_factors
