def max_sum_pair_diff_lessthan_K(arr, left, right, k):
    if right - left < 2:
        return max(arr[left], arr[right])

    pivot = arr[right]
    count_less = right - 1

    for i in range(right - 1, left - 1, -1):
        if arr[i] < pivot:
            arr[i], arr[count_less] = arr[count_less], arr[i]
            count_less -= 1

    arr[right], arr[count_less] = arr[count_less], arr[right]

    left_sum = max_sum_pair_diff_lessthan_K(arr, left, count_less - 1, k)
    right_sum = max_sum_pair_diff_lessthan_K(arr, count_less + 1, right, k)
    common_sum = pivot * 2

    if common_sum <= k:
        return max(left_sum, right_sum, common_sum)
    else:
        return max(left_sum, right_sum)
