def super_seq(str1, str2, n1, n2):
    # Create a 2D table to store lengths of common suffixes
    dp = [[0] * (n2 + 1) for _ in range(n1 + 1)]

    # Build the dp table in bottom-up manner
    for i in range(n1 + 1):
        for j in range(n2 + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
