def sum_of_square(n):
    # Base case: sum of square of 0 and 1 is 1
    if n == 0 or n == 1:
        return 1

    # Recursive case: sum of square of n is sum_square(n-1) + 2*binomial(n, n-1) + binomial(n, n)
    return sum_of_square(n - 1) + 2 * binomial(n, n - 1) + binomial(n, n)

def binomial(n, k):
    # Helper function to calculate binomial coefficient
    if k == 0 or k == n:
        return 1
    return binomial(n - 1, k - 1) + binomial(n - 1, k)

