def sum_of_square(n):
    # initialize the binomial coefficient matrix
    binomial_coefficient = [[0]*(n+1) for _ in range(n+1)]

    # fill the binomial coefficient matrix
    for i in range(n+1):
        for j in range(i+1):
            if j == 0 or j == i:
                binomial_coefficient[i][j] = 1
            else:
                binomial_coefficient[i][j] = binomial_coefficient[i-1][j-1] + binomial_coefficient[i-1][j]

    # calculate the sum of squares
    sum_of_squares = sum([binomial_coefficient[i][i] ** 2 for i in range(n+1)])

    return sum_of_squares
