    dp = [[0 for _ in range(n)] for _ in range(n)]
    lenght = [[1 for _ in range(n)] for _ in range(n)]

    # Calculate lengths of increasing subsequence
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                lenght[i][j] += lenght[j][i]
                dp[i][j] += dp[j][i]

    # Calculate lengths of decreasing subsequence
    for i in reversed(range(n)):
        for j in reversed(range(i)):
            if arr[j] > arr[i]:
                lenght[i][j] += lenght[j][i]
                dp[i][j] += dp[j][i]

