import re

def search_literal(original_string, literal_string):
    # Setup the search pattern
    pattern = r'\b' + re.escape(literal_string) + r'\b'

    # Perform the search
    matches = re.search(pattern, original_string)

    # Return the location if there's a match
    if matches:
