def max_sum_of_three_consecutive(nums, n):
    if n < 3:
        return 0
    dp = [0] * n
    dp[0] = nums[0]
    dp[1] = nums[0] + nums[1]
    dp[2] = max(nums[0], nums[1] + nums[2], nums[1] * nums[2], nums[0] * nums[2])
    for i in range(3, n):
        ans = 0
        for j in range(-1, 2):
            if i + j >= 0 and i + j < n:
                ans = max(ans, dp[i - 1])
            dp[i] = max(dp[i], dp[i - 1] + nums[i] + ans)
    return dp[-1]
