def rencontres_number(n, r):
    # Function to calculate the binomial coefficient
    def binomial_coefficient(n, r):
        return factorial(n) // (factorial(r) * factorial(n - r))

    # Calculate the n-th rencontres number
    total_count = 0
    for i in range(n + 1):
        count = binomial_coefficient(n, i) * binomial_coefficient(n, 1 - i)
        total_count += count * (2 ** i)

    return total_count
```

