def min_Swaps(str1, str2):
    n = len(str1)
    a_count, b_count = str1.count('0'), str2.count('1')

    if b_count != n - a_count:
        return -1

    max_x, min_x = -1, float('inf')

    if str1[0] != str2[0]:
        max_x = 1
        min_x = 0

    for i in range(1, n):
        if str1[i] != str2[i]:
            if str1[i] == str2[i - 1]:
                min_x += 1
            max_x += 1

    logging.debug(f"max_x -> {max_x}, min_x -> {min_x}")
    return min(min_x, max_x)
```

