def min_Swaps(s1, s2):
    n = len(s1)
    repeat_transforms = 0 

    # Counting the number of swaps required to transform s1 to s2
    for i in range(n):
        if s1[i] != s2[i] and repeat_transforms == 0:
            repeat_transforms += 1

    if s1 == s2:
        return 0

    if repeat_transforms % 2 != 0:
        return -1

    return repeat_transforms - 1
