def maximum_segments(n, a, b, c):
    # Ensure a <= b <= c
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    # Initialize segments
    num_segments = 0
    while n >= a:
        n -= a
        num_segments += 1
    while n >= b:
        n -= b
        num_segments += 1
    while n >= c:
        n -= c
        num_segments += 1
    return num_segments
