def min_cost(cost, m, n):
    # Initialize a 2D list to store the minimum cost to reach each position
    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = cost[0][0]  # Base case: cost to reach (0, 0) is equal to its value in the cost matrix

    # Fill the first row and first column of the dp matrix
    for i in range(1, m + 1):
        dp[i][0] = dp[i - 1][0] + cost[i][0]
    for j in range(1, n + 1):
        dp[0][j] = dp[0][j - 1] + cost[0][j]

    # Fill the rest of the dp matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = cost[i][j] + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[m][n]
```

```python
def min_cost(cost, m, n):
    if m < 0 or n < 0 or m >= len(cost) or n >= len(cost[0]):
        return float('inf')
    if m == n == 0:
        return cost[m][n]

    # Recursive case: move to (m-1, n) or (m, n-1), then choose the minimum cost
    return min(min_cost(cost, m-1, n), min_cost(cost, m, n-1)) + cost[m][n]
```

```python
def min_cost(cost, m, n):
    for i in range(1, m):
        cost[i][0] += cost[i-1][0]
    for j in range(1, n):
        cost[0][j] += cost[0][j-1]
    for i in range(1, m):
        for j in range(1, n):
            cost[i][j] += min(cost[i-1][j], cost[i][j-1], cost[i-1][j-1])
    return cost[m-1][n-1]
```

