def join_tuples(lst):
    result = []
    seen = set()
    for Tuple in lst:
        initial_elements = tuple(Tuple[:1])
        if initial_elements in seen:
            result[-1].extend(Tuple[1:])
        else:
            seen.add(initial_elements)
            result.append(list(Tuple) + [None])
    return tuple(tuple(item) if item is not None else tuple() for item in result)
```
