def remove_similar_row(matrix):
    seen = set()
    result = []
    for row in matrix:
        row_tuple = tuple(map(tuple, row))
        if row_tuple not in seen:
            result.append(row)
            seen.add(row_tuple)
    return set(map(tuple, result))

