from collections import defaultdict

def remove_similar_row(matrix):
    similar_rows = defaultdict(list)

    for row1, row2 in zip(matrix, [row[::-1] for row in matrix]):
        key = tuple(sorted(row1) + sorted(row2[::-1]))
        similar_rows[key].append((row1, row2))

    return {row for row in similar_rows.values() if len(row) > 1}
