def max_sum_of_three_consecutive(arr, n):
    dp = [0] * n

    # Initialize base cases
    dp[0] = arr[0]
    if n == 1:
        return max(dp)
    dp[1] = max(arr[0], arr[1])
    if n == 2:
        return max(dp)

    # Fill the dp array
    for i in range(2, n):
        dp[i] = max(arr[i] + dp[i-3], dp[i-2], dp[i-1])

    # Find the maximum value in the dp array
    maxSum = 0
    for i in range(n):
        maxSum = max(maxSum, dp[i])

    return maxSum
```

