def max_sum_of_three_consecutive(arr, n):
    if n < 3:
        return sum(arr)
    # Create an auxiliary array to store the maximum sum up to each index
    max_sum = [0] * n
    # Initialize the first three elements of the max_sum array
    max_sum[0], max_sum[1], max_sum[2] = arr[0], arr[1] + arr[0], arr[1] + arr[0] + arr[2]
    # Fill the max_sum array for the rest of the elements
    for i in range(3, n):
        max_sum[i] = max(max_sum[i - 1], max_sum[i - 3] + arr[i], max_sum[i - 2] + arr[i] + arr[i - 1])
    # Return the maximum sum found
    return max(max_sum)
```

