def max_sum_of_three_consecutive(arr, n):
    if n < 3:
        return 0
    if n == 3:
        return max(arr[0] + arr[1] + arr[2], arr[0] + arr[2])

    dp = [0] * n
    dp[0] = arr[0]
    dp[1] = arr[0] + arr[1]
    dp[2] = max(arr[0] + arr[1], arr[0] + arr[1] + arr[2])

    for i in range(3, n):
        dp[i] = max(dp[i-1], max(dp[i-2], dp[i-3])) + arr[i]

    return dp[n-1]
```

