def find_Max(arr, left, right):
    if right >= left:
        mid = left + (right - left) // 2

        # If the middle element is the maximum element
        if (mid == 0 or arr[mid] > arr[mid - 1]) and \
           (mid == len(arr) - 1 or arr[mid] > arr[mid + 1]):
            return arr[mid]

        # If the left half is sorted and maximum element is in it
        if arr[left] <= arr[mid]:
            return find_Max(arr, mid + 1, right)

        # If the right half is sorted and maximum element is in it
        return find_Max(arr, left, mid - 1)
    return -1  # If the array is not sorted, this line will never be reached
