def min_Swaps(A, B):
    swaps = 0
    for i in range(len(A)):
        if A[i] != B[i]:
            j = i + 1
            while j < len(A) and A[j] != B[i]:
                j += 1
            if j < len(A) and A[j] == B[i]:
                temp = A[i]
                A[i] = A[j]
                A[j] = temp
                swaps += 1
    return swaps
