def second_frequent(sequence):
    if len(sequence) < 2:
        return None  # Not enough elements to have a second frequent string

    string_count = {}
    for string in sequence:
        if string in string_count:
            string_count[string] += 1
        else:
            string_count[string] = 1

    sorted_strings = sorted(string_count.items(), key=lambda item: item[1], reverse=True)
    if len(sorted_strings) <= 1:
        return None  # No second frequent string

    return sorted_strings[1][0]
```

