class Solution(object):
    def kthElement(self, numbers1, numbers2, k, i, j):
        if len(numbers1) <= i:
            return numbers2[j]
        if len(numbers2) <= j:
            return numbers1[i]
        if i == k - 1:
            return min(numbers1[i], numbers2[j])
        mid_i = i + (k - 1) // 2
        mid_j = j + k // 2
        if numbers1[mid_i] <= numbers2[mid_j]:
            return self.kthElement(numbers1, numbers2, k, mid_i + 1, j)
        else:
            return self.kthElement(numbers1, numbers2, k, i, mid_j + 1)
