def find_kth(nums1, nums2, k1, k2, kth_num):
    idx1 = k1
    idx2 = k2
    while idx1 <= len(nums1) and idx2 <= len(nums2):
        if idx1 > k1:
            if nums1[idx1-1] > nums2[idx2-1]:
                nums1 = nums1[idx1:]
            else:
                nums2 = nums2[idx2:]
        elif idx2 > k2:
            if nums1[idx1-1] > nums2[idx2-1]:
                nums1 = nums1[:idx1]
            else:
                nums2 = nums2[:idx2]
        elif idx1 < k1:
            if nums1[idx1] < nums2[idx2]:
                idx1 += 1
            else:
                idx2 += 1
        elif idx2 < k2:
            if nums1[idx1] < nums2[idx2]:
                idx2 += 1
            else:
                idx1 += 1
    if idx1 > k1:
        return nums2[k2 - (idx1 - k1)]
    if idx2 > k2:
        return nums1[k1 - (idx2 - k2)]
    return nums1[k1 - 1]
