def find_kth(A, B, i, j, k):
    # Base case: if there are no elements left in either array, return -1
    if len(A) == 0:
        return B[j + k - 1]
    if len(B) == 0:
        return A[i + k - 1]

    # Compare the current elements of both arrays
    midA = (i + j) // 2
    midB = (i + j + k - 1) // 2

    if A[midA] > B[midB]:
        # If the element in A is greater, then the kth element can only be in the left half of A
        return find_kth(A, B[:midB + 1], i, midA, k)
    else:
        # If the element in A is less, then the kth element can only be in the right half of A
        return find_kth(A[midA + 1:], B, midA + 1, j, k - midA - 1)
```

