def find_kth(arr1, arr2, size1, size2, k):
    # Initialize two pointers
    i, j, count = 0, 0, 0

    # Traverse both arrays
    while i < size1 and j < size2:
        # If current element of first array is smaller, move to next element in first array
        if arr1[i] < arr2[j]:
            i += 1
        # Otherwise, move to next element in second array
        else:
            j += 1
        # Increment count
        count += 1

        # If count reaches k, return the current element
        if count == k:
            return arr1[i]

    # If k is greater than the total number of elements in either array, return the appropriate element
    if i == size1:
        return arr2[j + k - 1]
    else:
        return arr1[i + k - 1]
