def unique_sublists(l):
    seen = set()
    results = {}
    for sublist in l:
        tuple_sublist = tuple(sublist)
        if tuple_sublist not in seen:
            seen.add(tuple_sublist)
            results[tuple_sublist] = 1
        else:
            results[tuple_sublist] += 1
    return results
```

