def heap_sort(arr):
    def heapify(arr, length, i):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < length and arr[largest] < arr[left]:
            largest = left
        if right < length and arr[largest] < arr[right]:
            largest = right

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify(arr, length, largest)

    n = len(arr)

    # Build a max heap
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    # Run through array from last element to second element
    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]  # Swap root (maximum value) with the last element
        heapify(arr, i, 0)  # Heapify the root element

    return arr
