def super_seq(str1, str2, len1, len2):
    ans = difseq(str1, str2, len1, len2)
    return len(str1) + len(str2) - ans

def difseq(first, second, len1, len2):
    if len1 == 0:
        return len2
    if len2 == 0:
        return len1
    if first[len1-1] == second[len2-1]:
        return 1 + difseq(first, second, len1-1, len2-1)
    else:
        return 1 + min(difseq(first, second, len1, len2-1), difseq(first, second, len1-1, len2))
```

