def super_seq(str1, str2, len1, len2):
    # Initialize the matrix to store lengths of longest common subsequences
    lcs_matrix = [[0 for _ in range(len2 + 1)] for _ in range(len1 + 1)]

    # Fill the lcs_matrix in bottom up manner
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                lcs_matrix[i][j] = lcs_matrix[i - 1][j - 1] + 1
            else:
                lcs_matrix[i][j] = max(lcs_matrix[i - 1][j], lcs_matrix[i][j - 1])

    # The length of the longest common subsequence is the answer
    return lcs_matrix[len1][len2]
```

