import functools
def super_seq(a, b, m, n):
    @functools.lru_cache(None)
    def dp(i, j):
        if i == -1 or j == -1:
            return 0
        if a[i] == b[j]:
            return 1 + dp(i - 1, j - 1)
        else:
            return max(dp(i - 1, j), dp(i, j - 1))
    return dp(m - 1, n - 1) + m + n - 2 * dp(m - 1, n - 1)
```

