def dealnnoy_num(n, k):
    # Calculate the factorial of n and k
    fact_n = 1
    fact_k = 1
    fact_n_minus_k = 1
    for i in range(1, n + 1):
        fact_n *= i
    for i in range(1, k + 1):
        fact_k *= i
    for i in range(1, n - k + 1):
        fact_n_minus_k *= i

    # Calculate the Delannoy number
    deno = fact_n * fact_k * fact_n_minus_k
    return int(deno / (fact_k - 1))
```

