def dealnnoy_num(n, k):
    # Base case 1: The n-th delannoy number of k is 1 if k < n
    if k < n:
        return 1
    # Base case 2: The n-th delannoy number of 0 for any k is always 1
    elif k == 0:
        return 1
    # Recursive case: The n-th delannoy number is the sum of the (n-1)th delannoy numbers of k-1 and k
    else:
        return dealnnoy_num(n-1, k-1) + dealnnoy_num(n-1, k)
