def subset(nums, n):
    # Initialize a dictionary to keep track of subsets
    sub = {}
    size = 1
    # Loop through each number in the input list
    for i in range(1, n+1):
        # Check if subsets of the current size are present in the dictionary
        if (size - 1) in sub and i not in sub[size]:
            # If the number does not have the current subset, add it as an element to this subset
            sub[size] |= {i}
        # If no subsets of the current size are found, create a new subset with just this number
        else:
            sub[size] = {i}
        # Increase the size of the subset
        size += 1
    # Return the size of the largest subset found, which will be the minimum number of subsets required
    return size - 1
```

