def subset(nums, k):
    encountered = set()
    subsets = []
    seen = 0
    for num in nums:
        if num not in encountered:
            encountered.add(num)
            subsets.append([num])
            seen += 1
        else:
            found_in_previous = False
            for subset in subsets:
                if subset[-1] < num and num not in subset:
                    subset.append(num)
                    found_in_previous = True
                    break
            if not found_in_previous:
                subsets.append([num])
                seen += 1
        if seen >= k:
            break
    return len(subsets)
