def dealnnoy_num(n, k):
    # Initialize a 2D list to store the delannoy numbers
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Filling the first row and first column of the dp table
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(k + 1):
        dp[0][j] = 1

    # Fill the rest of the dp table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1] + dp[i][j - 1]

    # Return the nth delannoy number
    return dp[n][k]
```

