        result = [[1] * (i + 1) for i in range(n)]
        for i in range(1, n):
            for j in range(1, i + 1):
                result[i][j] = result[i - 1][j - 1] + result[i - 1][j] + result[i][j - 1]
        return result

    table = sliding_table(n)
    return table[r][n - r - 1]
```

