def count_Rotation(arr, n):
    low, high = 0, n - 1
    count = 0
    while low <= high:
        if arr[low] <= arr[high]:
            count += 1
            break
        mid = (low + high) // 2
        next = (mid + 1) % n
        prev = (mid - 1 + n) % n
        if arr[mid] <= arr[next] and arr[mid] <= arr[prev]:
            count += 1
            break
        elif arr[mid] <= arr[next]:
            high = mid - 1
        else:
            low = mid + 1
    return count
```

