def find_Max(arr, start, end):
    # Base case: if there's only one element, return that element
    if start == end:
        return arr[start]

    # Two pointers.Initialize one at the start and one at the end.
    mid = start + (end - start) // 2

    # Check if the middle element itself is the maximum.
    if mid == 0 or arr[mid] > arr[mid - 1]:
        return arr[mid]

    # Decide whether to go to the left or right half based on the middle element.
    if arr[mid] < arr[end]:
        # If the right half is sorted, the maximum element is in the left half.
        return find_Max(arr, start, mid - 1)
    else:
        # If the right half is not sorted, the maximum element is in the right half.
        return find_Max(arr, mid + 1, end)
```

