def max_sum_of_three_consecutive(arr, n):
    j, max_sum = 0, 0
    if n <= 0:
        return 0
    elif n <= 2:
        return sum(arr)

    for i in range(2, n):
        # Check if current element is not part of consecutive sum
        if arr[i - 1] > arr[i] <= arr[i + 1]:
            continue
        else:
            j += 1
            # Update max_sum if new combination gives maximum sum
            max_sum = max(max_sum, arr[i + j] + arr[i] + arr[i + j + 1])
    return max_sum
