    if n == 0:
        return 1
    if n == 1:
        return 1

    # Initialize the bell numbers list
    bell = [0] * (n + 1)
    bell[0], bell[1] = 1, 1

    # Fill the bell numbers array using the recurrence relation
    for i in range(2, n + 1):
        for j in range(i):
            bell[i] += bell[j]

    return bell[n]
