import math

def min_Jumps(x1, y1, x2):
    jump_count = 0
    next_y = 0
    prev_y1 = 0

    while next_y < x2:
        if x2 - next_y < x1:
            next_y = x1
        else:
            next_y += x1

        if next_y > x2 / 2:
            prev_y1 = next_y

        jump_count += 1

    if (x2 - prev_y1) >= abs(next_y - y1):
        jump_count += 1 + math.ceil(((x2 - prev_y1) - abs(next_y - y1)) / x1)

    return round(jump_count + 1.5)  # The additional 1.5 is for the distance to go from prev_y1 to (d, 0)
```

