def find_kth(arr1, arr2, k1, k2, k):
    # Iterate from both arrays until we find the kth element
    while k1 <= len(arr1) and k2 <= len(arr2):
        if k1 == k:
            return arr1[k1 - 1]
        if k2 == k:
            return arr2[k2 - 1]
        if arr1[k1] < arr2[k2]:
            k1 += 1
        else:
            k2 += 1
        k += 1

    # If either array is exhausted, return the last element of the remaining array
    if k1 > len(arr1):
        return arr2[k2 + k - 1]
    else:
        return arr1[k1 + k - 1]
