def find_kth(arr1, arr2, index1, index2, k):
    n1, n2 = len(arr1), len(arr2)

    if index1 >= n1:
        return arr2[index2 + k - 1]
    elif index2 >= n2:
        return arr1[index1 + k - 1]

    if k == 1:
        return min(arr1[index1], arr2[index2])

    mid1, mid2 = (index1 + k // 2 - 1) % n1, (index2 + k // 2 - 1) % n2
    if arr1[mid1] < arr2[mid2]:
        return find_kth(arr1, arr2, mid1 + 1, index2, k - mid1
    else:
        return find_kth(arr1, arr2, index1, mid2 + 1, k - mid2)
