def get_median(arr1, arr2, n):
    misalign = n // 2
    i, j = 0, 0
    count = 0

    while i < n and j < n:
        if arr1[i] <= arr2[j]:
            count += 1
        if count == misalign + 1:
            return arr1[i]
        if count == misalign:
            return (arr1[i] + arr2[j]) / 2.0
        if arr1[i] > arr2[j]:
            j += 1
        else:
            i += 1

    # If there're remaining elements in arr1
    while i < n:
        count += 1
        if count == misalign + 1:
            return arr1[i]
        if count == misalign:
            return (arr1[i] + arr2[n - 1]) / 2.0
        i += 1

    # If there're remaining elements in arr2
    while j < n:
        count += 1
        if count == misalign + 1:
            return arr2[j]
        if count == misalign:
            return (arr1[n - 1] + arr2[j]) / 2.0
        j += 1
