def maxAverageOfPath(matrix, n):
    def helper(i, j, visited, acc, count):
        if i < 0 or j < 0 or i >= n or j >= n or visited[i][j]:
            return
        acc += matrix[i][j]
        count += 1
        visited[i][j] = True
        if count == n:
            return max(acc, acc / count)
        return max(helper(i-1, j, visited, acc, count),
                  helper(i+1, j, visited, acc, count),
                  helper(i, j-1, visited, acc, count),
                  helper(i, j+1, visited, acc, count))

    visited = [[False for _ in range(n)] for _ in range(n)]
    return helper(0, 0, visited, 0, 0)
