def maxAverageOfPath(matrix, n):
    def dfs(x, y, path, s):
        if x < 0 or y < 0 or x >= n or y >= n or sum(path) >= s:
            return 0
        if len(path) == n:
            return sum(path) / len(path)
        return max(dfs(x - 1, y, path + [matrix[x][y]], s),
                   dfs(x + 1, y, path + [matrix[x][y]], s),
                   dfs(x, y - 1, path + [matrix[x][y]], s),
                   dfs(x, y + 1, path + [matrix[x][y]], s))

    max_avg = 0
    for s in range(n * n + 1):
        max_avg = max(max_avg, dfs(0, 0, [], s))
    return max_avg
