def occurance_substring(text, pattern):
    occurrence = {}
    start = 0
    while start < len(text):
        index = text.find(pattern, start)
        if index != -1:
            if pattern in occurrence:
                occurrence[pattern].append(index)
            else:
                occurrence[pattern] = [index]
            start = index + 1
        else:
            break
    return (pattern, occurrence[pattern][0], occurrence[pattern][-1])
