def unique_sublists(lists):
    non_unique_lists = []
    unique_list_dict = {}

    # Check if the list is not empty
    if lists:
        for index, sublist in enumerate(lists):
            if sublist not in non_unique_lists and sublist not in unique_list_dict:
                non_unique_lists.append(sublist)
                unique_list_dict[sublist] = 1
            # Increment count if sublist is already in unique_list_dict
            elif sublist in unique_list_dict:
                unique_list_dict[sublist] += 1
    # Create a dictionary from the list of unique lists
    unique_list_dict = {tuple sublist: unique_list_dict[sublist] for sublist in unique_list_dict}
