def hamming_distance(x, y):
    distance = 0
    while x > 0 and y > 0:
        if x % 2 != y % 2:
            distance += 1
        x >>= 1
        y >>= 1
    while x > 0:
        if x % 2 != 0:
            distance += 1
        x >>= 1
    while y > 0:
        if y % 2 != 0:
            distance += 1
        y >>= 1
    return distance
```

